43	#include "llvm/ADT/SmallVector.h"
44	#include "llvm/Support/Debug.h"
45	
46	using namespace mlir;
47	
48	static constexpr const char *DEBUG_TYPE = "data-dependency-analysis";
49	#define LOG_DEBUG(...)                                                         \
50	  LLVM_DEBUG(llvm::dbgs() << " [" << DEBUG_TYPE << "] " << __VA_ARGS__)
51	
52	using namespace mlir::triton;
53	using namespace mlir::CVPipeline;
54	
55	// Attribute name constants
56	static constexpr const char *ssbufferCoreTypeCubeAttr = "CUBE";
57	static constexpr const char *ssbufferCoreTypeVectorAttr = "VECTOR";
58	static constexpr int ND_SHAPE_LENGTH = 2;
59	static constexpr int SHAPE_1D_LENGTH = 1;
60	
61	// Helper: ssbuffer.core_type
62	llvm::StringRef getSsbufferCoreType(Operation *op) {
63	  if (auto attr = op->getAttrOfType<mlir::StringAttr>(CVPipeline::kCoreType)) {
64	    return attr.getValue();
65	  }
66	  return "";
67	}
68	
69	// Helper: Get CoreType from op and index
70	llvm::StringRef getCoreTypeWithIndex(Operation *op, int index) {
71	  llvm::StringRef typeStr = getSsbufferCoreType(op);
72	  if (typeStr.contains(", ")) {
73	    llvm::SmallVector<llvm::StringRef> types;
74	    typeStr.split(types, ", ", -1, false);
75	    if (index < types.size()) {
76	      return types[index].trim();
77	    }
78	    LOG_DEBUG("Warning: Core type string has multiple types but value is not "
79	              "an OpResult or index out of range.\n");
80	    return "";
81	  }
82	
83	  return typeStr;
84	}
85	
86	// Helper: Check if operation is control flow
87	bool DataDependencyAnalysisPass::isControlFlowOp(mlir::Operation *op) {
88	  if (!op)
89	    return false;
90	  return isa<scf::ForOp>(op) || isa<scf::IfOp>(op) || isa<scf::YieldOp>(op);
91	}
92	
93	bool DataDependencyAnalysisPass::isCubeOrVectorOp(mlir::Operation *op) {
94	  if (isa<tensor::EmptyOp, linalg::FillOp>(op)) {
95	    return true;
96	  }
97	  return false;
98	}
99	
100	bool DataDependencyAnalysisPass::isValidShapeForDependency(mlir::Value value) {
101	  auto tensorTy = dyn_cast<TensorType>(value.getType());
102	  if (!tensorTy) {
103	    return false;
104	  }
105	
106	  if (tensorTy.getRank() != ND_SHAPE_LENGTH) {
107	    return false;
108	  }
109	  return true;
110	}
111	
112	bool DataDependencyAnalysisPass::isValidScalarDependency(mlir::Value value) {
113	  if (isa<mlir::IntegerType, mlir::FloatType>(value.getType())) {
114	    auto defOp = value.getDefiningOp();
115	    if (defOp && isa<tensor::ExtractOp>(defOp)) {
116	      return true;
117	    }
118	  }
119	  return false;
120	}
121	
122	bool DataDependencyAnalysisPass::isValid1DValueForDependency(
123	    mlir::Value value) {
124	  auto tensorTy = dyn_cast<TensorType>(value.getType());
125	  if (tensorTy && tensorTy.getRank() == SHAPE_1D_LENGTH) {
126	    return true;
127	  }
128	  return false;
129	}
130	
131	// Check if a value is only used by transpose ops whose users are all vector ops
132	bool DataDependencyAnalysisPass::isAllTransposedInVector(mlir::Value value) {
133	  if (!isa<linalg::MatmulOp>(value.getDefiningOp())) {
134	    return false;
135	  }
136	  if (!llvm::hasSingleElement(value.getUsers())) {
137	    return false;
138	  }
139	  auto *userOp = *value.getUsers().begin();
140	  if (!isa<linalg::TransposeOp>(userOp))
141	    return false;
142	  for (mlir::Operation *transposeOpUser : userOp->getUsers()) {
143	    if (getSsbufferCoreType(transposeOpUser) != ssbufferCoreTypeVectorAttr)
144	      return false;
145	  }
146	  return true;
147	}
148	
149	// Helper: Check if value is a valid tensor for dependency analysis
150	// Returns true if value is TensorType and not defined by EmptyOp/FillOp
151	bool DataDependencyAnalysisPass::isValidValueForDependency(mlir::Value value) {
152	  if (isValidScalarDependency(value)) {
153	    return true;
154	  }
155	  if (isValid1DValueForDependency(value)) {
156	    return true;
157	  }
158	  if (!isValidShapeForDependency(value)) {
159	    return false;
160	  }
161	
162	  Operation *defOp = value.getDefiningOp();
163	  // Op that can be processed both by CUBE and VECTOR should not be data
164	  // dependency
165	  if (defOp && isCubeOrVectorOp(defOp)) {
166	    return false;
167	  }
168	
169	  return true;
170	}
171	
172	// Helper: Check if value is a BlockArgument
173	bool DataDependencyAnalysisPass::isOuterOpArg(mlir::Value value) {
174	  if (auto blockArg = mlir::dyn_cast<mlir::BlockArgument>(value)) {
175	    mlir::Block *ownerBlock = blockArg.getOwner();
176	    return true;
177	  }
178	  return false;
179	}
180	
181	// Helper: Build and record BlockInfo
182	void DataDependencyAnalysisPass::collectBlockInfo(
183	    DataDependencyInfo &info, int blockId,
184	    llvm::SmallVector<mlir::Operation *> &ops) {
185	  if (ops.empty()) {
186	    LOG_DEBUG("Warning: Block ID " << blockId << " has no operations.\n");
187	    return;
188	  }
189	
190	  BlockInfo blockInfo;
191	  blockInfo.blockId = blockId;
192	  blockInfo.isCube = false;
193	
194	  // In cases with one or more core_types
195	  // as long as there is a cube, it is necessary to check the dataflow.
196	  StringRef coreType = getSsbufferCoreType(ops[0]);
197	  if (coreType.contains(ssbufferCoreTypeCubeAttr)) {
198	    blockInfo.isCube = true;
199	  }
200	
201	  blockInfo.isControl = false;
202	  if (isControlFlowOp(ops[0])) {
203	    blockInfo.isControl = true;
204	  }
205	
206	  llvm::DenseSet<mlir::Operation *> opSet(ops.begin(), ops.end());
207	
208	  for (auto *op : ops) {
209	    blockInfo.Operations.push_back(op);
210	    for (auto operand : op->getOperands()) {
211	      mlir::Operation *defOp = operand.getDefiningOp();
212	      // If defOp is not null and defOp is not in current ops set, it's an
213	      // external input
214	      if (!defOp || opSet.find(defOp) == opSet.end()) {
215	        blockInfo.inputs.insert(operand);
216	      }
217	    }
218	    for (auto result : op->getResults()) {
219	      // If any user is not in the current ops set, it's an external output
220	      bool hasExternalUser = false;
221	      for (mlir::Operation *user : result.getUsers()) {
222	        if (opSet.find(user) == opSet.end()) {
223	          hasExternalUser = true;
224	          break;
225	        }
226	      }
227	      if (hasExternalUser) {
228	        blockInfo.outputs.push_back(result);
229	      }
230	    }
231	  }
232	
233	  info.getBlockInfoMap()[blockInfo.blockId] = blockInfo;
234	
235	  LOG_DEBUG("Block_ID=" << blockInfo.blockId << "Processed!\n");
236	}
237	
238	// Block Information Collection
239	void DataDependencyAnalysisPass::createBlockInfoMap(DataDependencyInfo &info) {
240	  int currentId = -2;
241	  static constexpr int startCurrId = -2;
242	  llvm::SmallVector<mlir::Operation *> currentOps;
243	
244	  module.walk([&](mlir::Operation *op) {
245	    auto opBlockIdOpt = CVPipeline::getOpBlockId(op);
246	    if (opBlockIdOpt) {
247	      int opBlockId = *opBlockIdOpt;
248	      // When the id changes, the block ends && Exclude the initial state
249	      if (opBlockId != currentId && currentId != startCurrId) {
250	        collectBlockInfo(info, currentId, currentOps);
251	        currentOps.clear();
252	      }
253	      currentId = opBlockId;
254	      currentOps.push_back(op);
255	    }
256	  });
257	  // Process the last group
258	  if (!currentOps.empty()) {
259	    collectBlockInfo(info, currentId, currentOps);
260	  }
261	}
262	
263	void DataDependencyAnalysisPass::collectDepInfo(
264	    mlir::Value depvalue, DependencyType dependencyType,
265	    llvm::SmallVector<DependencyInfo> &dependencies, int iniProdId,
266	    int iniConsId, DataDependencyInfo &info, bool isAllTranspoesd) {
267	  DependencyInfo depInfo;
268	  depInfo.type = dependencyType;
269	  depInfo.value = depvalue;
270	  LOG_DEBUG("try finding common level block IDs\n");
271	  depInfo.iniProducerBlockId = iniProdId;
272	  depInfo.iniConsumerBlockId = iniConsId;
273	  std::pair<int, int> commonLevelIds =
274	      findCommonLevelBlockIds(info, iniProdId, iniConsId);
275	  if (commonLevelIds.first == -1 || commonLevelIds.second == -1) {
276	    LOG_DEBUG("Could not find common level block IDs for producer and consumer "
277	              "blocks");
278	    CVPipeline::setFallbackAttr(module, CVPipeline::ERRCODE_FAILED);
279	    return;
280	  }
281	
282	  depInfo.producerBlockId = commonLevelIds.first;
283	  depInfo.consumerBlockId = commonLevelIds.second;
284	  if (isValidScalarDependency(depvalue)) {
285	    depInfo.isScaler = true;
286	  }
287	  if (isValid1DValueForDependency(depvalue)) {
288	    depInfo.is1DTensor = true;
289	  }
290	  if (isAllTranspoesd) {
291	    depInfo.isAllTranspoesd = true;
292	  }
293	  dependencies.push_back(depInfo);
294	}
