296	// Collects users of iterArg that have a different core type than initCoreType.
297	llvm::SmallVector<mlir::Operation *>
298	DataDependencyAnalysisPass::collectDiffCoreTypeUsers(
299	    mlir::BlockArgument iterArg, llvm::StringRef initCoreType) {
300	  llvm::SmallVector<mlir::Operation *> diffUsers;
301	
302	  for (mlir::Operation *user : iterArg.getUsers()) {
303	    if (isa<scf::YieldOp>(user)) {
304	      continue;
305	    }
306	    if (isControlFlowOp(user)) {
307	      LOG_DEBUG("cannot process nested iterarg!");
308	      continue;
309	    }
310	
311	    auto userCoreType = getCoreTypeWithIndex(user, 0);
312	    if (userCoreType != initCoreType && !userCoreType.empty()) {
313	      diffUsers.push_back(user);
314	    }
315	  }
316	
317	  return diffUsers;
318	}
