320	// Inserts a producer block at the beginning of the for loop body and records
321	// cross-core-type dependencies for each user in diffUsers.
322	void DataDependencyAnalysisPass::insertProducerAndRecordDeps(
323	    scf::ForOp forOp, mlir::BlockArgument iterArg, llvm::StringRef initCoreType,
324	    llvm::SmallVector<mlir::Operation *> &diffUsers, DataDependencyInfo &info) {
325	  auto &v2cDependencies = info.getV2CDependencies();
326	  auto &c2vDependencies = info.getC2VDependencies();
327	  auto &blockInfoMap = info.getBlockInfoMap();
328	
329	  int newId = CVPipeline::getAvailableBlockId(module);
330	  OpBuilder builder(forOp);
331	  Block &bodyBlock = forOp.getRegion().front();
332	  builder.setInsertionPointToStart(&bodyBlock);
333	  Location loc = forOp.getLoc();
334	  auto constOp = builder.create<arith::ConstantIntOp>(loc, 0, 32);
335	  setOpBlockId(constOp, newId);
336	  setOpCoreType(constOp, initCoreType);
337	
338	  BlockInfo blockInfo;
339	  blockInfo.blockId = newId;
340	  blockInfo.isCube = (initCoreType == ssbufferCoreTypeCubeAttr);
341	  blockInfo.isControl = false;
342	  blockInfo.Operations.push_back(constOp);
343	  blockInfoMap[newId] = blockInfo;
344	
345	  for (auto &user : diffUsers) {
346	    auto userBlockIdOpt = CVPipeline::getOpBlockId(user);
347	    if (!userBlockIdOpt) {
348	      LOG_DEBUG("Warning: User block ID not found for iterArg user.\n");
349	      continue;
350	    }
351	    int userBlockId = *userBlockIdOpt;
352	
353	    // Determine dependency type based on initCoreType
354	    DependencyType depType;
355	    if (initCoreType == ssbufferCoreTypeVectorAttr) {
356	      depType = DependencyType::VectorToCube;
357	    } else if (initCoreType == ssbufferCoreTypeCubeAttr) {
358	      depType = DependencyType::CubeToVector;
359	    } else {
360	      LOG_DEBUG("Warning: Unknown initCoreType: " << initCoreType << "\n");
361	      continue;
362	    }
363	
364	    // Record dependency
365	    DependencyInfo depInfo;
366	    depInfo.type = depType;
367	    depInfo.value = iterArg;
368	    depInfo.iniProducerBlockId = newId;
369	    depInfo.iniConsumerBlockId = userBlockId;
370	
371	    auto [producerBlockId, consumerBlockId] =
372	        findCommonLevelBlockIds(info, newId, userBlockId);
373	    depInfo.producerBlockId = producerBlockId;
374	    depInfo.consumerBlockId = consumerBlockId;
375	    if (isValid1DValueForDependency(iterArg)) {
376	      depInfo.is1DTensor = true;
377	    }
378	    if (depType == DependencyType::VectorToCube) {
379	      v2cDependencies.push_back(depInfo);
380	    } else {
381	      c2vDependencies.push_back(depInfo);
382	    }
383	
384	    LOG_DEBUG("Recorded iterArg dependency: "
385	              << initCoreType << " -> "
386	              << (depType == DependencyType::VectorToCube
387	                      ? ssbufferCoreTypeCubeAttr
388	                      : ssbufferCoreTypeVectorAttr)
389	              << ", producerBlockId=" << newId
390	              << ", consumerBlockId=" << userBlockId << "\n");
391	  }
392	}
393	
394	bool checkYieldCoreType(mlir::Operation *yieldOp) {
395	  if (!isa<scf::YieldOp>(yieldOp)) {
396	    return false;
397	  }
398	  for (unsigned index = 0; index < yieldOp->getNumOperands(); ++index) {
399	    mlir::Value value = yieldOp->getOperand(index);
400	    llvm::StringRef yieldCoreType = getCoreTypeWithIndex(yieldOp, index);
401	
402	    mlir::Operation *definingOp = value.getDefiningOp();
403	    if (!definingOp || !isa<scf::ForOp>(definingOp)) {
404	      continue;
405	    }
406	    auto defResult = dyn_cast<mlir::OpResult>(value);
407	    int resultIndex = defResult ? defResult.getResultNumber() : 0;
408	    llvm::StringRef definingCoreType =
409	        getCoreTypeWithIndex(definingOp, resultIndex);
410	
411	    if (yieldCoreType != definingCoreType) {
412	      return false;
413	    }
414	  }
415	  return true;
416	}
