418	// Process iterArg dependencies for all scf.for operations in the module.
419	// This function iterates through all for loops and checks each iterArg to
420	// determine if there are cross-core-type data dependencies.
421	void DataDependencyAnalysisPass::processIterArgDependencies() {
422	  auto &info = getAnalysis<DataDependencyInfo>();
423	
424	  // Step1: Collect all scf.for operations in the module
425	  llvm::SmallVector<scf::ForOp> forOps;
426	  module.walk([&](scf::ForOp forOp) { forOps.push_back(forOp); });
427	  LOG_DEBUG("Processing iterArg dependencies, found " << forOps.size()
428	                                                      << " scf.for ops\n");
429	
430	  // Step2: Process each iterArg of each scf.for operation
431	  for (scf::ForOp forOp : forOps) {
432	    size_t numIterArgs = forOp.getInitArgs().size();
433	    mlir::Operation *yieldOp = forOp.getBody()->getTerminator();
434	    if (!checkYieldCoreType(yieldOp)) {
435	      LOG_DEBUG("[ERROR]: Yield core type mismatch defining op\n");
436	      signalPassFailure();
437	    }
438	    for (int iterArgIndex = 0; iterArgIndex < numIterArgs; ++iterArgIndex) {
439	      mlir::Value initValue = forOp.getInits()[iterArgIndex];
440	      mlir::BlockArgument iterArg = forOp.getRegionIterArg(iterArgIndex);
441	      mlir::Value yieldedValue = forOp.getYieldedValues()[iterArgIndex];
442	      LOG_DEBUG("initValue" << initValue << "\n");
443	      LOG_DEBUG("yieldedValue" << yieldedValue << "\n");
444	
445	      if (!isValid1DValueForDependency(iterArg) &&
446	          (!isValidShapeForDependency(initValue) ||
447	           !isValidShapeForDependency(yieldedValue))) {
448	        LOG_DEBUG("iterarg: " << iterArg
449	                              << " is not valid tensor for dependency!");
450	        continue;
451	      }
452	
453	      Operation *initDefOp = initValue.getDefiningOp();
454	      Operation *yieldedDefOp = yieldedValue.getDefiningOp();
455	      if (!initDefOp) {
456	        LOG_DEBUG("warning: nested iterarg!");
457	        continue;
458	      }
459	      if (!yieldedDefOp) {
460	        continue;
461	      }
462	      if (isCubeOrVectorOp(initDefOp) && isCubeOrVectorOp(yieldedDefOp)) {
463	        continue;
464	      }
465	
466	      auto initDefResult = dyn_cast<mlir::OpResult>(initValue);
467	      auto initCoreType = getCoreTypeWithIndex(
468	          initDefOp, initDefResult ? initDefResult.getResultNumber() : 0);
469	      auto yieldCoreType = getCoreTypeWithIndex(forOp, iterArgIndex);
470	
471	      // Only process if init and yield have matching core types
472	      // Mismatch indicates a more complex dependency pattern that requires
473	      // special handling
474	      if (initCoreType != yieldCoreType) {
475	        if (!isValidValueForDependency(initValue)) {
476	          if (collectDiffCoreTypeUsers(iterArg, yieldCoreType).empty()) {
477	            continue;
478	          }
479	        }
480	        LOG_DEBUG("iterarg init core_type conflicts with yield");
481	        CVPipeline::setFallbackAttr(module, CVPipeline::ERRCODE_FAILED);
482	        return;
483	      }
484	
485	      auto diffUsers = collectDiffCoreTypeUsers(iterArg, initCoreType);
486	      if (!diffUsers.empty()) {
487	        insertProducerAndRecordDeps(forOp, iterArg, initCoreType, diffUsers,
488	                                    info);
489	      }
490	    }
491	  }
492	}
