630	void DataDependencyAnalysisPass::collectMemDepInfo(
631	    llvm::StringRef predCoreType, int producerBlockId, int consumerBlockId,
632	    int predBlockId, int currBlockId,
633	    llvm::SmallVector<DependencyInfo> &memoryDependencies,
634	    mlir::Operation *predOp, mlir::Operation *nextOp) {
635	  DependencyInfo depInfo;
636	
637	  if (predCoreType == ssbufferCoreTypeCubeAttr) {
638	    depInfo.type = DependencyType::CubeToVector;
639	  } else if (predCoreType == ssbufferCoreTypeVectorAttr) {
640	    depInfo.type = DependencyType::VectorToCube;
641	  }
642	  depInfo.producerBlockId = producerBlockId;
643	  depInfo.consumerBlockId = consumerBlockId;
644	  depInfo.iniProducerBlockId = predBlockId;
645	  depInfo.iniConsumerBlockId = currBlockId;
646	
647	  depInfo.predOp = predOp;
648	  depInfo.nextOp = nextOp;
649	
650	  memoryDependencies.push_back(depInfo);
651	}
